import { describe, expect, it } from "vitest";
import oracle from "./__fixtures__/oracle.json";
import { lahiriAyanamsa } from "./ayanamsa";
import { retrogradeFlags, siderealAscendant, siderealGrahaLongitudes } from "./ephemeris";
import { angleDiff, julianDay } from "./math";

// Fixture generated by scripts/guru/generate_oracle.py using Swiss Ephemeris
// as an independent oracle (dev-time only). Tolerances sit just above the
// errors actually measured across all cases (see comments), so a regression
// in the maths shows up immediately without the tests being flaky.

const PLANETS = ["Sun", "Moon", "Mars", "Mercury", "Jupiter", "Venus", "Saturn"] as const;

describe("Lahiri ayanamsa", () => {
  it("is 23.857092 degrees at J2000 (anchor value)", () => {
    expect(lahiriAyanamsa(2_451_545.0)).toBeCloseTo(23.857092, 4);
  });

  it("matches the oracle across 1925-2040 (measured max error 0.00004 deg)", () => {
    for (const c of oracle.cases) {
      expect(Math.abs(lahiriAyanamsa(julianDay(new Date(c.utc))) - c.ayanamsa)).toBeLessThan(0.0005);
    }
  });
});

describe("sidereal planetary longitudes vs Swiss Ephemeris", () => {
  it.each(PLANETS)("%s within 0.01 deg (about 36 arcsec) in every case", (graha) => {
    for (const c of oracle.cases) {
      const { longitudes } = siderealGrahaLongitudes(new Date(c.utc));
      const expected = (c.bodies as Record<string, { sidereal: number }>)[graha].sidereal;
      expect(Math.abs(angleDiff(longitudes[graha], expected)), `${graha} @ ${c.utc}`).toBeLessThan(0.01);
    }
  });

  it("mean node (Rahu) within 0.001 deg", () => {
    for (const c of oracle.cases) {
      const { longitudes } = siderealGrahaLongitudes(new Date(c.utc), "mean");
      expect(Math.abs(angleDiff(longitudes.Rahu, c.bodies.MeanNode.sidereal)), c.utc).toBeLessThan(0.001);
    }
  });

  it("true node (Rahu) within 0.03 deg (different lunar theories; measured max 0.016)", () => {
    for (const c of oracle.cases) {
      const { longitudes } = siderealGrahaLongitudes(new Date(c.utc), "true");
      expect(Math.abs(angleDiff(longitudes.Rahu, c.bodies.TrueNode.sidereal)), c.utc).toBeLessThan(0.03);
    }
  });

  it("Ketu is always exactly opposite Rahu", () => {
    const { longitudes } = siderealGrahaLongitudes(new Date("1989-12-21T20:40:00Z"));
    expect(Math.abs(angleDiff(longitudes.Ketu, longitudes.Rahu + 180))).toBeLessThan(1e-9);
  });
});

describe("sidereal ascendant vs Swiss Ephemeris", () => {
  it("within 0.001 deg for every location and time, both hemispheres", () => {
    for (const c of oracle.cases) {
      const asc = siderealAscendant(new Date(c.utc), c.latitude, c.longitude);
      expect(Math.abs(angleDiff(asc, c.ascendantSidereal)), c.utc).toBeLessThan(0.001);
    }
  });
});

describe("retrograde flags", () => {
  it("agree with the oracle's motion sign (skipping near-stationary cases)", () => {
    for (const c of oracle.cases) {
      const flags = retrogradeFlags(new Date(c.utc));
      for (const graha of ["Mars", "Mercury", "Jupiter", "Venus", "Saturn"] as const) {
        const speed = (c.bodies as Record<string, { speed: number }>)[graha].speed;
        if (Math.abs(speed) < 0.02) continue; // stationary: 24h sign is legitimately ambiguous
        expect(flags[graha], `${graha} @ ${c.utc}`).toBe(speed < 0);
      }
    }
  });

  it("Sun and Moon are never retrograde; mean nodes always are", () => {
    const flags = retrogradeFlags(new Date("2000-01-01T12:00:00Z"));
    expect(flags.Sun).toBe(false);
    expect(flags.Moon).toBe(false);
    expect(flags.Rahu).toBe(true);
    expect(flags.Ketu).toBe(true);
  });
});
